import{_ as e,o as r,c as o,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-03-05","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-03-05","date":"2025-03-05T00:00:00.000Z","updated":"2025-03-11T00:00:00.000Z","tags":["Ceph","RGW","Encryption","Storage","COE"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-03-05.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-03-05.md","lastUpdated":1780460162000}'),i={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-03-05.md"};function n(s,t,l,g,p,c){return r(),o("div",null,[...t[0]||(t[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>: 未知<br><strong>参会人员</strong>: 团队成员</p><h4 id="主要议题" tabindex="-1">主要议题: <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题:&quot;">​</a></h4><ol><li><p><strong>持久化队列（persistent queue）升级问题</strong></p><ul><li><strong>问题描述</strong>: 从Reef升级到Squid时，持久化队列的统计数据（topic stats）显示不正确，因为Reef中没有进行队列计数，升级后计数器从零开始。</li><li><strong>讨论内容</strong>: 讨论了三种解决方案，包括在升级后初始化计数器、遍历所有队列条目以填充正确的统计数据或添加一个<code>reset stats</code>命令。</li><li><strong>决定事项</strong>: 决定进一步研究在CLS级别计算队列条目数量的可能性，确保统计数据的正确性。</li><li><strong>后续行动</strong>: 团队成员将深入研究相关代码，检查是否可以在CLS级别进行计数。</li></ul></li><li><p><strong>Marcus的Copy Object Encryption（COE）测试</strong></p><ul><li><strong>问题描述</strong>: Marcus的COE测试需要Vault实例和存储类设置，团队需要评估哪些部分可以在S3测试中使用。</li><li><strong>讨论内容</strong>: 确定了S3测试已设置的部分存储类，并需要确定测试脚本是否需要访问Vault客户端，并确保在测试前后密钥数量一致。</li><li><strong>决定事项</strong>: 决定将COE测试脚本集成到现有的rgw Crypt Vault Transit测试中。</li><li><strong>后续行动</strong>: Marcus将继续调试压缩问题，并与其他团队成员合作，确保COE测试的顺利集成。</li></ul></li><li><p><strong>CVE修复PR的合并</strong></p><ul><li><strong>问题描述</strong>: 关于Reef RGW RADOS对象删除的CVE修复PR，是否需要将其合并到当前的18.2.5版本中。</li><li><strong>讨论内容</strong>: 认为该问题已存在较长时间，但不认为是当前版本的阻塞问题，决定在测试完成后合并或在下一个版本中合并。</li><li><strong>决定事项</strong>: 该PR的合并将根据测试结果决定，可能会在下一个版本中合并。</li></ul></li></ol><h4 id="其他讨论" tabindex="-1">其他讨论: <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论:&quot;">​</a></h4><ul><li><strong>压缩问题</strong>: Marcus正在调试与压缩相关的问题，初步判断可能与下游的7.1版本有关。</li></ul><h4 id="总结" tabindex="-1">总结: <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结:&quot;">​</a></h4><p>本次会议主要讨论了以下议题：</p><ul><li>持久化队列升级后的统计数据问题；</li><li>Marcus的COE测试集成；</li><li>CVE修复PR的合并问题。</li></ul><p>团队决定进一步研究持久化队列的统计数据问题，并确保COE测试的顺利集成。CVE修复PR的合并将根据测试结果决定。同时，还讨论了与压缩相关的问题。</p>',10)])])}const d=e(i,[["render",n]]);export{u as __pageData,d as default};
